-- Generated by analytics/export_sap.py: SAP S/4HANA-style tables for the Boréal Viandes extract.
CREATE SCHEMA BOREAL;

-- MARA: General material data
CREATE COLUMN TABLE BOREAL.MARA (
    MATNR        NVARCHAR(40),   -- Material
    MTART        NVARCHAR(4),    -- Material type (HAWA = trading goods)
    MATKL        NVARCHAR(9),    -- Material group
    MEINS        NVARCHAR(3),    -- Base unit (CS = case)
    BRGEW        DECIMAL(13,3),  -- Gross weight per case
    NTGEW        DECIMAL(13,3),  -- Net weight per case
    GEWEI        NVARCHAR(3),    -- Weight unit
    EAN11        NVARCHAR(18),   -- GTIN-14 of the case
    MHDHB        INTEGER,        -- Total shelf life (days)
    RAUBE        NVARCHAR(2),    -- Storage conditions (room FR/TR/CG)
    XCHPF        NVARCHAR(1),    -- Batch management (X)
    ZZCATCH      NVARCHAR(1)     -- Catch weight (X)
);

-- MAKT: Material descriptions
CREATE COLUMN TABLE BOREAL.MAKT (
    MATNR        NVARCHAR(40),   -- Material
    SPRAS        NVARCHAR(1),    -- Language (F, E)
    MAKTX        NVARCHAR(40)    -- Description
);

-- MARM: Units of measure
CREATE COLUMN TABLE BOREAL.MARM (
    MATNR        NVARCHAR(40),   -- Material
    MEINH        NVARCHAR(3),    -- Unit (CS case, ST piece)
    UMREZ        INTEGER,        -- Numerator: base units
    UMREN        INTEGER,        -- Denominator: alternative units
    EAN11        NVARCHAR(18)    -- GTIN of this unit
);

-- MCH1: Batches
CREATE COLUMN TABLE BOREAL.MCH1 (
    MATNR        NVARCHAR(40),   -- Material
    CHARG        NVARCHAR(10),   -- Batch (lot)
    HSDAT        NVARCHAR(8),    -- Production (pack) date
    VFDAT        NVARCHAR(8),    -- Best-before date
    LIFNR        NVARCHAR(10)    -- Vendor (plant)
);

-- LFA1: Vendors
CREATE COLUMN TABLE BOREAL.LFA1 (
    LIFNR        NVARCHAR(10),   -- Vendor
    NAME1        NVARCHAR(35),   -- Name
    LAND1        NVARCHAR(3),    -- Country
    REGIO        NVARCHAR(3)     -- Region
);

-- KNA1: Customers
CREATE COLUMN TABLE BOREAL.KNA1 (
    KUNNR        NVARCHAR(10),   -- Customer (store)
    NAME1        NVARCHAR(35),   -- Name
    ORT01        NVARCHAR(35),   -- City
    LAND1        NVARCHAR(3),    -- Country
    REGIO        NVARCHAR(3),    -- Region
    KDGRP        NVARCHAR(10),   -- Customer group (grocery, club, restaurant)
    ZZROUTE      NVARCHAR(6),    -- Delivery route
    ZZSTOP       INTEGER         -- Stop on the route
);

-- EKKO: Purchase order headers
CREATE COLUMN TABLE BOREAL.EKKO (
    EBELN        NVARCHAR(10),   -- Purchase order
    BSART        NVARCHAR(4),    -- Order type (NB)
    LIFNR        NVARCHAR(10),   -- Vendor
    BEDAT        NVARCHAR(8),    -- Order date
    ZZEINDT      NVARCHAR(8),    -- Scheduled delivery date
    ZZEINTM      NVARCHAR(6),    -- Scheduled delivery time
    ZZPAL_ORD    INTEGER         -- Pallets ordered
);

-- EKPO: Purchase order items (cases received per material)
CREATE COLUMN TABLE BOREAL.EKPO (
    EBELN        NVARCHAR(10),   -- Purchase order
    EBELP        NVARCHAR(5),    -- Item
    MATNR        NVARCHAR(40),   -- Material
    WERKS        NVARCHAR(4),    -- Plant
    MENGE        DECIMAL(13,3),  -- Quantity
    MEINS        NVARCHAR(3)     -- Unit
);

-- MATDOC: Material documents (inventory postings)
CREATE COLUMN TABLE BOREAL.MATDOC (
    MBLNR        NVARCHAR(10),   -- Material document
    MJAHR        NVARCHAR(4),    -- Year
    ZEILE        NVARCHAR(4),    -- Item
    BWART        NVARCHAR(3),    -- Movement type
    SHKZG        NVARCHAR(1),    -- Debit S / credit H
    MATNR        NVARCHAR(40),   -- Material
    WERKS        NVARCHAR(4),    -- Plant
    LGORT        NVARCHAR(4),    -- Storage location
    CHARG        NVARCHAR(10),   -- Batch
    INSMK        NVARCHAR(1),    -- Stock type (X = quality inspection)
    MENGE        DECIMAL(13,3),  -- Quantity
    MEINS        NVARCHAR(3),    -- Unit
    BUDAT        NVARCHAR(8),    -- Posting date
    CPUDT        NVARCHAR(8),    -- Entry date
    CPUTM        NVARCHAR(6),    -- Entry time
    USNAM        NVARCHAR(12),   -- User
    EBELN        NVARCHAR(10),   -- Purchase order
    LIFNR        NVARCHAR(10),   -- Vendor
    SGTXT        NVARCHAR(50)    -- Item text (reason)
);

-- LTAP: Warehouse tasks: every confirmed scan, bin to bin
CREATE COLUMN TABLE BOREAL.LTAP (
    LGNUM        NVARCHAR(3),    -- Warehouse number
    TANUM        NVARCHAR(10),   -- Transfer order
    TAPOS        NVARCHAR(4),    -- Item
    BWLVS        NVARCHAR(3),    -- Movement type (999 = internal move)
    ZZSCAN       NVARCHAR(3),    -- Scan type (RCV, TXI, PUT, PCK, BLD, LOD, SHP...)
    MATNR        NVARCHAR(40),   -- Material
    CHARG        NVARCHAR(10),   -- Batch
    VLPLA        NVARCHAR(18),   -- Source bin
    NLPLA        NVARCHAR(18),   -- Destination bin
    VLENR        NVARCHAR(20),   -- Source storage unit (SSCC)
    NLENR        NVARCHAR(20),   -- Destination storage unit (SSCC)
    VSOLM        DECIMAL(13,3),  -- Quantity (cases)
    ALTME        NVARCHAR(3),    -- Unit
    BRGEW        DECIMAL(13,3),  -- Weight (kg)
    QNAME        NVARCHAR(12),   -- Confirmed by
    QDATU        NVARCHAR(8),    -- Confirmation date
    QZEIT        NVARCHAR(6)     -- Confirmation time
);

-- VBAK: Sales order headers
CREATE COLUMN TABLE BOREAL.VBAK (
    VBELN        NVARCHAR(10),   -- Sales order
    AUART        NVARCHAR(4),    -- Order type (OR, ZRUS = rush)
    KUNNR        NVARCHAR(10),   -- Sold-to (store)
    ERDAT        NVARCHAR(8),    -- Created on
    ERZET        NVARCHAR(6),    -- Created at
    VDATU        NVARCHAR(8),    -- Requested delivery date
    NETWR        DECIMAL(15,2)   -- Net value
);

-- VBAP: Sales order items
CREATE COLUMN TABLE BOREAL.VBAP (
    VBELN        NVARCHAR(10),   -- Sales order
    POSNR        NVARCHAR(6),    -- Item
    MATNR        NVARCHAR(40),   -- Material
    KWMENG       DECIMAL(15,3),  -- Ordered quantity
    VRKME        NVARCHAR(3)     -- Sales unit
);

-- LIKP: Outbound delivery headers
CREATE COLUMN TABLE BOREAL.LIKP (
    VBELN        NVARCHAR(10),   -- Delivery
    LFART        NVARCHAR(4),    -- Delivery type (LF)
    KUNNR        NVARCHAR(10),   -- Ship-to (store)
    ROUTE        NVARCHAR(6),    -- Route
    VSART        NVARCHAR(2),    -- Shipping type (01 route truck, 02 expedited)
    WADAT        NVARCHAR(8),    -- Planned goods issue date
    WAUHR        NVARCHAR(6),    -- Planned goods issue time
    WADAT_IST    NVARCHAR(8),    -- Actual goods issue date
    ZZWAUHR_IST  NVARCHAR(6)     -- Actual goods issue time
);

-- LIPS: Outbound delivery items (one per batch shipped)
CREATE COLUMN TABLE BOREAL.LIPS (
    VBELN        NVARCHAR(10),   -- Delivery
    POSNR        NVARCHAR(6),    -- Item
    MATNR        NVARCHAR(40),   -- Material
    CHARG        NVARCHAR(10),   -- Batch
    LFIMG        DECIMAL(13,3),  -- Delivered quantity
    VRKME        NVARCHAR(3),    -- Unit
    VGBEL        NVARCHAR(10)    -- Reference sales order
);

-- VBFA: Sales document flow (order -> delivery)
CREATE COLUMN TABLE BOREAL.VBFA (
    VBELV        NVARCHAR(10),   -- Preceding document (sales order)
    VBELN        NVARCHAR(10),   -- Subsequent document (delivery)
    VBTYP_N      NVARCHAR(1)     -- Subsequent category (J = delivery)
);
